def digsum(n):
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

print(digsum(2025), is_prime(97), is_prime(91))

